import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.dMg474VA.js";const p=JSON.parse('{"title":"Project Pitch: Distributed Rate-Limiting API Gateway","description":"","frontmatter":{},"headers":[],"relativePath":"00b-project-pitch.md","filePath":"00b-project-pitch.md"}'),o={name:"00b-project-pitch.md"};function n(s,e,c,d,l,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="project-pitch-distributed-rate-limiting-api-gateway" tabindex="-1">Project Pitch: Distributed Rate-Limiting API Gateway <a class="header-anchor" href="#project-pitch-distributed-rate-limiting-api-gateway" aria-label="Permalink to &quot;Project Pitch: Distributed Rate-Limiting API Gateway&quot;">​</a></h1><h2 id="_30-second-elevator-pitch" tabindex="-1">30-Second Elevator Pitch <a class="header-anchor" href="#_30-second-elevator-pitch" aria-label="Permalink to &quot;30-Second Elevator Pitch&quot;">​</a></h2><blockquote><p>&quot;I built an enterprise-grade distributed rate-limiting API gateway in TypeScript and Redis that protects downstream microservices from traffic surges, brute-force attacks, and noisy tenants. It supports five distinct rate-limiting algorithms—including Token Bucket and Sliding Window Counter—executed via atomic Redis Lua scripts to eliminate race conditions. If Redis fails, the gateway gracefully degrades to an in-memory fallback without blocking traffic, and a React dashboard visualizes live quota consumption and anomaly alerts.&quot;</p></blockquote><hr><h2 id="_2-minute-technical-interview-pitch" tabindex="-1">2-Minute Technical Interview Pitch <a class="header-anchor" href="#_2-minute-technical-interview-pitch" aria-label="Permalink to &quot;2-Minute Technical Interview Pitch&quot;">​</a></h2><blockquote><p>&quot;When microservices experience traffic spikes or DDoS attacks, traditional application-level rate limiting either fails due to distributed race conditions or causes cascading database failures.</p><p>To solve this, I designed and built <strong>16-Rate-Limit-Gateway</strong>, a high-performance distributed gateway control plane.</p><p>At its core, the gateway implements five industry-standard rate limiting algorithms in <code>src/algorithms/</code>: Token Bucket, Leaky Bucket, Fixed Window, Sliding Window Log, and Sliding Window Counter.</p><p>To guarantee atomicity across clustered servers, I wrote specialized Redis Lua scripts in <code>packages/store-redis/</code>. A single atomic Redis evaluation fetches current bucket counts, computes token replenishment, deducts the request cost, and sets TTL expiration in one round-trip. This completely eliminates the classic check-then-set race condition where concurrent requests exceed quota limits.</p><p>For resilience, I implemented a Circuit Breaker pattern on the Redis storage layer. If Redis latency spikes or the cluster partitions, the gateway transitions within 50 milliseconds to an in-memory lock-free store, logging a degraded warning while ensuring zero dropped traffic for legitimate callers.</p><p>The gateway includes a dynamic Policy Matcher in <code>src/policy/</code> supporting weighted route costs, header-based quota overrides, and CIDR subnet blocking. The administrative dashboard is built in React 19 and Vite, streaming live throttling metrics. The system is hardened by 25 Vitest integration suites and property-based tests using <code>fast-check</code>.&quot;</p></blockquote>',6)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
